                | extend max_TimeGenerated = datetime_add('hour',1,max_TimeGenerated)
        ),
        (
            print({TimeRange:start})
            | extend max_TimeGenerated = print_0
            | project max_TimeGenerated
        )
        | summarize maxTimeGenerated = max(max_TimeGenerated) 
    );
let DNSData =    
union isfuzzy=true 
    (
        _Im_Dns(starttime=todatetime(maxSummarizedTime), endtime=now())
        | where ('{SrcIpAddr}' == '*' or (SrcIpAddr == '{SrcIpAddr}'))
            and ('{DnsQuery}' == '*' or (DnsQuery == '{DnsQuery}'))
        | where isnotempty(DnsQuery)
        | summarize DNSEvents=tolong(count()) by DnsQuery, bin(TimeGenerated,6h)
    ),
    (
        DNS_Summarized_Logs_ip_CL
        | where TimeGenerated >= {TimeRange:start}
        | where ('{SrcIpAddr}' == '*' or (SrcIpAddr_s == '{SrcIpAddr}'))
            and ('{DnsQuery}' == '*' or (DnsQuery_s == '{DnsQuery}'))
        | where isnotempty(DnsQuery_s)
        | summarize DNSEvents=tolong(sum(count__d)) by DnsQuery=DnsQuery_s, bin(TimeGenerated=EventTime_t,6h)
    )
    | summarize DNSEvents = sum(DNSEvents) by DnsQuery, bin(TimeGenerated, 6h);
    DNSData
    //Break the domain into its parts
    | extend DomainParts = split(DnsQuery,'.')
    //Use the rightmost parts of the URL
    | extend Top_Level_Domain =  strcat(DomainParts[toint(array_length(DomainParts)-2)],'.',DomainParts[toint(array_length(DomainParts)-1)])
    //If the two right most parts are too short (e.g. "co.uk" or "com.tr", add another part
    | extend Top_Level_Domain = iif(strlen(Top_Level_Domain)<7,strcat(DomainParts[toint(array_length(DomainParts)-3)],'.',Top_Level_Domain),Top_Level_Domain)
    | summarize SubDomainRequestCount = toint(sum(DNSEvents)) by Top_Level_Domain, DnsQuery
    | join kind=inner 
    (
            DNSData
            //Break the domain into its parts
            | extend DomainParts = split(DnsQuery,'.')
            //Use the rightmost parts of the URL
            | extend Top_Level_Domain =  strcat(DomainParts[toint(array_length(DomainParts)-2)],'.',DomainParts[toint(array_length(DomainParts)-1)])
            //If the two right most parts are too short (e.g. "co.uk" or "com.tr", add another part
            | extend Top_Level_Domain = iif(strlen(Top_Level_Domain)<7,strcat(DomainParts[toint(array_length(DomainParts)-3)],'.',Top_Level_Domain),Top_Level_Domain)
            | summarize DomainRequestCount = toint(sum(DNSEvents)) by Top_Level_Domain
    ) on Top_Level_Domain
    | extend pk = SubDomainRequestCount/todouble(DomainRequestCount)
    //calculate entropy according to Shannon function https://en.wiktionary.org/wiki/Shannon_entropy
    | extend h1= -log2(pk)*pk
    | summarize SubDomainEntropy = sum(h1), DomainRequestCount = any(DomainRequestCount) ,DNSQueries=make_list(DnsQuery)  by TopLevelDomain=Top_Level_Domain
    | order by SubDomainEntropy desc
    | take 25

// Specify the IP Address or FQDN of the Endace InvestigationManager (or EndaceProbe) and Rotation File Name
let Endace_IM = "<FQDN>";
let Endace_Rotfile = "main";
// Specify the default tools
let Endace_Tools = "conversations_by_ninetuple%2CtrafficOverTime_by_app";
// Identify the Database
CommonSecurityLog
// We're using the following DB fields to build the Pivot-to-Vision URL:
// SourceIP, DestinationIP, TimeGenerated
// Limit our search to 'Threat' records
| where Activity == "THREAT"
| extend p2v_ip = case(
    isnotnull(SourceIP) and isnotnull(DestinationIP), strcat("&ip_conv=", SourceIP, "%20%26%20", DestinationIP),
    isnotnull(SourceIP), strcat("&ip=", SourceIP),
    isnotnull(DestinationIP), strcat("&ip=", DestinationIP),
    ""
  )
// Set the URL Variable
| extend Endace_p2v = strcat("https://", Endace_IM, "/vision2/pivotintovision/?datasources=", Endace_Rotfile, "&title=Pivot+From+Sentinel", p2v_ip, "&tools=", Endace_Tools, "&incidenttime=", tostring(TimeGenerated))
// Display the new Table
| project TimeGenerated, Activity, Message, SourceIP, DestinationIP, Endace_p2v
// Set a record limit
| limit 5

_ASim_ProcessEvent_Create
| where Process has "certutil.exe"
// Uncomment the next line and add your commandLine Whitelisted/ignore terms. For example "urlcache"
// | where CommandLine !contains ("urlcache")

let timeframe = 1d;
let executableExtensions = dynamic([".js", ".hta", ".lnk", ".application", ".vb", ".vba", ".vbs", ".ps", ".ps1", ".bat", ".cmd"]);
DeviceFileEvents
| where Timestamp >= ago(timeframe)
| where InitiatingProcessFileName in~ ("winword.exe", "excel.exe", "outlook.exe", "powerpnt.exe")
| where ActionType == "FileRenamed"
// The mv-apply is less performance compared to doing a full written out !endswith. We kept the mv-apply since We don't hit any limits and get more readable/maintainable code.
| mv-apply ext=executableExtensions to typeof(string) on
(
    where PreviousFileName !endswith ext and FileName endswith ext
)
| project-reorder PreviousFileName, FileName
