let maxSummarizedTime = toscalar (
    union isfuzzy=true 
        (
            NetworkCustomAnalytics_protocol_CL
                | where EventTime_t >= {TimeRange:start}
                | summarize max_TimeGenerated=max(EventTime_t)
                | extend max_TimeGenerated = datetime_add('minute',10,max_TimeGenerated)
        ),
        (
            print({TimeRange:start})
            | extend max_TimeGenerated = print_0
            | project max_TimeGenerated
        )
        | summarize maxTimeGenerated = max(max_TimeGenerated) 
    );
union isfuzzy=true 
    (
        _Im_NetworkSession(starttime=todatetime(maxSummarizedTime), endtime=now(), dvcaction=actions)
	  | where isnotempty(DstPortNumber) and NetworkDirection == "Outbound"
	  | summarize Instances=toint(count()) by toint(DstPortNumber)
    ),
    (
        NetworkCustomAnalytics_protocol_CL
        | where EventTime_t >= {TimeRange:start}
	  | where isnotempty(DstPortNumber_d) and NetworkDirection_s == "Outbound"
	  | summarize Instances=toint(sum(count__d)) by DstPortNumber=toint(DstPortNumber_d)
    )
    | summarize Instances = sum(Instances) by DstPortNumber
    | extend DstPortNumber = tostring(DstPortNumber)
    | order by Instances
    | take 5
