let maxSummarizedTime = toscalar (
    union isfuzzy=true 
        (
            NetworkCustomAnalytics_threat_CL
                | where EventTime_t >= {TimeRange:start}
                | summarize max_TimeGenerated=max(EventTime_t)
                | extend max_TimeGenerated = datetime_add('minute',10,max_TimeGenerated)
        ),
        (
            print({TimeRange:start})
            | extend max_TimeGenerated = print_0
            | project max_TimeGenerated
        )
        | summarize maxTimeGenerated = max(max_TimeGenerated) 
    );
let distinctThreatCategory = 
union isfuzzy=true 
    (
        _Im_NetworkSession(starttime=todatetime(maxSummarizedTime),endtime=now())
		| where isnotempty(ThreatCategory)
    ),
    (  
        NetworkCustomAnalytics_threat_CL
		| where isnotempty(ThreatCategory_s)
		| extend ThreatCategory = ThreatCategory_s
    )
    | summarize Count=dcount(ThreatCategory)
    | extend Product = "Distinct Threat Categories", orderNum = 1
;
let distinctThreats = 
union isfuzzy=true 
    (
        _Im_NetworkSession(starttime=todatetime(maxSummarizedTime),endtime=now())
        | extend Threat = coalesce(ThreatId,ThreatName)
		| where isnotempty(Threat)
    ),
    (  
        NetworkCustomAnalytics_threat_CL
		| where isnotempty(Threat_s)
		| extend Threat = Threat_s
    )
    | summarize Count=dcount(Threat)
    | extend Product = "Distinct Threats", orderNum = 2
;
union distinctThreatCategory, distinctThreats
| order by orderNum asc
