---
_Im_NetworkSession(starttime={TimeRange:start},endtime={TimeRange:end})
| where SrcIpAddr == "{SearchIP}" or DstIpAddr == "{SearchIP}"
| summarize count() by EventProduct
---
_Im_NetworkSession(starttime={TimeRange:start},endtime={TimeRange:end})
| where SrcIpAddr == "{SearchIP}" or DstIpAddr == "{SearchIP}"
| summarize count() by NetworkProtocol
---
_Im_NetworkSession(starttime={TimeRange:start},endtime={TimeRange:end})
| where SrcIpAddr == "{SearchIP}" or DstIpAddr == "{SearchIP}"
| summarize count() by NetworkDirection
---
ThreatIntelligenceIndicator
| where NetworkIP == "{SearchIP}" and Active
| summarize arg_max(TimeGenerated,*) by NetworkIP
| project TimeGenerated, NetworkIP, Action, ConfidenceScore, Description, ExternalIndicatorId, ExpirationDateTime, IndicatorId, ThreatType, TrafficLightProtocolLevel
| evaluate narrow()
| project-away Row
---
SecurityAlert
| where Entities has "{SearchIP}"
| project TimeGenerated, DisplayName, AlertName, AlertSeverity, ProviderName, VendorName, SystemAlertId, StartTime, EndTime, todynamic(ExtendedProperties), Entities
