let maxSummarizedTimeIp = toscalar (
    union isfuzzy=true 
        (
            NetworkSummary_IP_CL
                | where EventTime >= {TimeRange:start}
                | summarize max_TimeGenerated=max(EventTime)
                | extend max_TimeGenerated = datetime_add('hour',1,max_TimeGenerated)
        ),
        (
            print({TimeRange:start})
            | extend max_TimeGenerated = print_0
            | project max_TimeGenerated
        )
        | summarize maxTimeGenerated = max(max_TimeGenerated) 
    );
let maxSummarizedTimeSource = toscalar (
    union isfuzzy=true 
        (
            NetworkSummary_SourceInfo_CL
                | where EventTime >= {TimeRange:start}
                | summarize max_TimeGenerated=max(EventTime)
                | extend max_TimeGenerated = datetime_add('minute',20,max_TimeGenerated)
        ),
        (
            print({TimeRange:start})
            | extend max_TimeGenerated = print_0
            | project max_TimeGenerated
        )
        | summarize maxTimeGenerated = max(max_TimeGenerated) 
    );
let totalConnection = 
union isfuzzy=true 
    (
        _Im_NetworkSession(starttime=todatetime(maxSummarizedTimeIp),endtime=now())
		| where isnotempty(SrcIpAddr) and isnotempty(DstIpAddr)
		| summarize count() by SrcIpAddr, DstIpAddr
    ),
    (  
        NetworkSummary_IP_CL
		| where isnotempty(SrcIpAddr) and isnotempty(DstIpAddr)
		| summarize count() by SrcIpAddr, DstIpAddr
    )
    | summarize count() by SrcIpAddr, DstIpAddr
    | count
    | extend Product = "Total Connections", orderNum = 1
;
let products = 
union isfuzzy=true 
    (
        _Im_NetworkSession(starttime=todatetime(maxSummarizedTimeSource),endtime=now())
		| extend EventProduct = strcat(EventVendor,"-",EventProduct)
        | distinct EventProduct
    ),
    (  
        NetworkSummary_SourceInfo_CL
		| distinct EventProduct
		| extend EventProduct=EventProduct
    )
    | distinct EventProduct
    | count
    | extend Product = "Different Products", orderNum = 2
;
let sources = 
union isfuzzy=true 
    (
        _Im_NetworkSession(starttime=todatetime(maxSummarizedTimeIp),endtime=now())
		| where isnotempty(SrcIpAddr)
		| summarize count() by SrcIpAddr
    ),
    (  
        NetworkSummary_IP_CL
		| where isnotempty(SrcIpAddr)
		| summarize count() by SrcIpAddr
    )
    | summarize count() by SrcIpAddr
    | count
    | extend Product = "Unique Sources", orderNum = 3
;
let destinations = 
union isfuzzy=true 
    (
        _Im_NetworkSession(starttime=todatetime(maxSummarizedTimeIp),endtime=now())
		| where isnotempty(DstIpAddr)
		| summarize count() by DstIpAddr
    ),
    (  
        NetworkSummary_IP_CL
		| where isnotempty(DstIpAddr)
		| summarize count() by DstIpAddr
    )
    | summarize count() by DstIpAddr
    | count
    | extend Product = "Unique Destinations", orderNum = 4
;
let blockedTraffic = 
union isfuzzy=true 
    (
        _Im_NetworkSession(starttime=todatetime(maxSummarizedTimeIp),endtime=now(),dvcaction=dynamic(["Deny","Drop"]))
		| where isnotempty(SrcIpAddr) and isnotempty(DstIpAddr)
		| summarize count() by SrcIpAddr, DstIpAddr
    ),
    (  
        NetworkSummary_IP_CL
		| where DvcAction in ("Deny","Drop")
		| where isnotempty(SrcIpAddr) and isnotempty(DstIpAddr)
		| summarize count() by SrcIpAddr, DstIpAddr
    )
    | summarize count() by SrcIpAddr,DstIpAddr
    | count
    | extend Product = "Blocked Traffic", orderNum = 5
;
union totalConnection, products, sources, destinations, blockedTraffic
| order by orderNum asc
