                | extend max_TimeGenerated = datetime_add('hour',1,max_TimeGenerated)
        ),
        (
            print({TimeRange:start})
            | extend max_TimeGenerated = print_0
            | project max_TimeGenerated
        )
        | summarize maxTimeGenerated = max(max_TimeGenerated) 
    );
let getIps = union isfuzzy=true 
    (
        _Im_NetworkSession(starttime=todatetime(maxSummarizedTime),endtime=now())
        | extend Threat = coalesce(ThreatId,ThreatName)
        | where isnotempty(Threat)
		| where NetworkDirection == "Inbound"
		| where isnotempty(SrcIpAddr)
		| distinct SrcIpAddr
    ),
    (  
        NetworkSummary_Threat_IOC_CL
		| where NetworkDirection == "Inbound"
		| where isnotempty(SrcIpAddr)
		| distinct SrcIpAddr
    )
    | distinct SrcIpAddr;
ThreatIntelligenceIndicator
| where NetworkIP in (getIps)
| order by TimeGenerated, ConfidenceScore
| project TimeGenerated, NetworkIP, Action, ConfidenceScore, Description, ExternalIndicatorId, ExpirationDateTime, IndicatorId, ThreatType
| take 10
