---
let list_tlds = ThreatIntelIndicators
| where TimeGenerated {Threat_Intelligence_Time_Range:query}
// Picking up only Recorded Future IOC's that are pertinent to the use case (Malware C2 Detection)
| where Data.description == {RF_Risk_list:value}
| where ObservableKey == 'domain-name:value'
 | where isnotempty(ObservableValue)
| where isnotempty(Tags)
| extend parts = split(ObservableValue, '.')
| extend tld = parts[(array_length(parts)-1)]
| summarize count() by tostring(tld)
| summarize make_list(tld);
ThreatIntelIndicators
| where TimeGenerated {Threat_Intelligence_Time_Range:query}
| where IsActive == true
// Picking up only Recorded Future IOC's that are pertinent to the use case (Malware C2 Detection)
| where Data.description == {RF_Risk_list:value}
// Picking up only IOC's that contain the entities we want
| where ObservableKey == 'domain-name:value'
 | where isnotempty(ObservableValue)
| where isnotempty(Tags)
| join (
    {Domain_Logs_Table:value}
    | where TimeGenerated  {Domain_Logs_Time_Range:query}
    //Extract Domain patterns from syslog message
    | where isnotempty({Domain_Logs_Field:value})
    | extend parts = split({Domain_Logs_Field:value}, '.')
    //Split out the TLD
    | extend tld = parts[(array_length(parts)-1)]
    //Validate parsed Domain by checking if the TLD is in the list of TLDs in our threat feed
    | where tld in~ (list_tlds)
    | extend DNS_TimeGenerated = TimeGenerated
) on $left.ObservableValue==$right.{Domain_Logs_Field:value}
| summarize Correlation_Matches=count() by bin(DNS_TimeGenerated, 1d)
| render barchart
