let getAmountOfIncedentForRuleId = (classification:string,status:string){
SecurityIncident
    | project TimeGenerated, Status, Classification, RelatedAnalyticRuleIds, AdditionalData
    | where TimeGenerated >= {TimeRange:start} and TimeGenerated <= {TimeRange:end}
    | where Status == status and Classification == classification
    | mv-expand RuleId=RelatedAnalyticRuleIds
    | extend RuleId=tostring(RuleId)
    | extend AlertProductNames = todynamic(AdditionalData)["alertProductNames"]
    | mv-expand AlertProductName =AlertProductNames
    | extend  AlertProductName=tostring(AlertProductName)
    | project AlertProductName,RuleId
    | where  isProductMarked(AlertProductName)!=-1 or alertText has RuleId
    | extend RuleId=iff(AlertProductName!= 'Azure Sentinel', AlertProductName, RuleId)
    | summarize counter=count() by RuleId
};

let falsePositiveClassificationTable = getAmountOfIncedentForRuleId("FalsePositive","Closed") | extend FalsePositiveCounter=counter | project-away counter;
let undeterminedClassificationTable = getAmountOfIncedentForRuleId("Undetermined","Closed") | extend UndeterminedCounter=counter | project-away counter;
let benignPositiveClassificationTable = getAmountOfIncedentForRuleId("BenignPositive","Closed") | extend BenignPositiveCounter=counter | project-away counter;
let truePositiveClassificationTable = getAmountOfIncedentForRuleId("TruePositive","Closed") | extend TruePositiveCounter=counter | project-away counter;
let activeIncedentTable = getAmountOfIncedentForRuleId("","Active") | extend ActiveIncedentsCounter=counter | project-away counter;    
let newIncedentTable = getAmountOfIncedentForRuleId("","New") | extend NewIncedentsCounter=counter | project-away counter;
let joinByRuleId = (T:(RuleId:string), S:(RuleId:string)){
    T 
    | join kind=fullouter S on $left.RuleId == $right.RuleId
    | extend RuleId= iff(RuleId == '', RuleId1,RuleId)
    | project-away RuleId1
};
joinByRuleId(joinByRuleId(joinByRuleId(joinByRuleId(joinByRuleId(falsePositiveClassificationTable, undeterminedClassificationTable) , benignPositiveClassificationTable), truePositiveClassificationTable),activeIncedentTable), newIncedentTable)
// Adding the Rule name to the table(we want to display name and not ID) 
| join kind=leftouter  
(SecurityAlert | project TimeGenerated, ProductName, ExtendedProperties
| where TimeGenerated >= {TimeRange:start} and TimeGenerated <= {TimeRange:end}
| where ProductName  ==  'Azure Sentinel'
| extend RuleId = parsejson( tostring(todynamic(ExtendedProperties)['Analytic Rule Ids']))
| mv-expand RuleId=RuleId
| extend RuleId=tostring(RuleId)
| extend RuleName=  tostring(todynamic(ExtendedProperties)['Analytic Rule Name'])
| project RuleId,RuleName
| distinct RuleId,RuleName)
 on $left.RuleId==$right.RuleId
| extend RuleName=iff(isempty(RuleName),RuleId,RuleName)
| project-away RuleId1
| where alertText has RuleId or isProductMarked(RuleName)!=-1  
| project-away RuleId
| extend TotalAlerts= iff(isempty(FalsePositiveCounter),0,FalsePositiveCounter) + 
iff(isempty(UndeterminedCounter),0,UndeterminedCounter)+ 
iff(isempty(BenignPositiveCounter),0,BenignPositiveCounter)+
iff(isempty(TruePositiveCounter),0,TruePositiveCounter) +
iff(isempty(ActiveIncedentsCounter),0,ActiveIncedentsCounter) +
iff(isempty(NewIncedentsCounter),0,NewIncedentsCounter)
| where TotalAlerts>0
| sort by TotalAlerts desc 
| project-away TotalAlerts 

