let getRuleNameIdTable = (){
    let alertText =  strcat_array(dynamic([{AlertRuleID}]),",");
    let RuleName =  strcat_array(dynamic([{RuleName}]),",");
    let rulesData = range x from 0 to array_length(split(alertText,','))-1 step 1
    | extend AlertRuleId= tostring(split(alertText,',')[x]),
    RuleName=tostring(split(RuleName,',')[x]);
    rulesData
};
let GetAlertRuleTable = (){
    let proerties = dynamic([{prop}]);
    let TmpRuleTable = datatable (MockColumn:string)["Mock"];
    TmpRuleTable
    | mv-expand SingleRuleProperties=proerties
    | project-away MockColumn
    | extend 
    Product=iff(SingleRuleProperties.productFilter!='',SingleRuleProperties.productFilter,"Azure Sentinel"), 
    RuleName=tostring(SingleRuleProperties.displayName), 
    MITRE_Tactics=iff(SingleRuleProperties.tactics!='',SingleRuleProperties.tactics,dynamic([])),
    Description=SingleRuleProperties.description
    | extend Status= iff(SingleRuleProperties.enabled==true,'Enabled',iff(RuleName startswith 'AUTO DISABLED','Auto disabled', 'Disabled'))
    | project-away SingleRuleProperties
    | join getRuleNameIdTable() on $left.RuleName==$right.RuleName
    | project-away RuleName1,x
};
let AlertAmount = materialize( SecurityAlert
| project ExtendedProperties,ProductName, ProviderName,TimeGenerated
| where TimeGenerated >= {TimeRange:start} and TimeGenerated <= {TimeRange:end}
| extend AnalyticRuleIdStr = replace('\"','',tostring(todynamic(ExtendedProperties)["Analytic Rule Ids"]))
| extend AnaliticRulesInAlertArray= split(substring(AnalyticRuleIdStr,1,string_size(AnalyticRuleIdStr)-2),",")
| mv-expand SingleAnaliticRuleID=AnaliticRulesInAlertArray
| extend SingleAnaliticRuleID=iff(ProductName=="Azure Sentinel",tostring(SingleAnaliticRuleID),ProductName)
| summarize AlertAmount=count() by SingleAnaliticRuleID
| extend AlertAmount=iff(AlertAmount>0,AlertAmount,0));
GetAlertRuleTable()
| join kind=leftouter AlertAmount on $left.AlertRuleId==$right.SingleAnaliticRuleID 
| project-away SingleAnaliticRuleID
| extend AlertAmount=iff(AlertAmount>0 or Product!= 'Azure Sentinel',AlertAmount,0)
| join kind=leftouter AlertAmount on $left.Product==$right.SingleAnaliticRuleID
| extend AlertAmount=iff(Product!= 'Azure Sentinel',AlertAmount1,AlertAmount)
| extend AlertAmount=iff(AlertAmount>0,AlertAmount,0)
| project-away AlertAmount1
| sort by AlertAmount desc
| project Status,Product,RuleName,AlertAmount
